-- Full 40-proposition evaluation for the Page's single-cash-lot UPDATE.
-- SQLite backend SQL composed around actual GProM REENACT-generated SQL.
-- This is ONE read-only backend statement, not nested GProM frontend syntax.
-- Six named parameters are bound from the frozen original candidate SELECT:
-- :allocation_id, :account_id, :statement_id, :payment_id, :batch_id,
-- :proposed_cash_dollars. Never accept an arbitrary caller-chosen batch_id.
-- Evaluate on the same stable snapshot used for selection/context derivation.
-- Proposed and old target values are generated by GProM; no table is changed.
-- All compliance facts are computed below from raw evidence in this statement.
-- P24 field meanings include accrued finance charges and avoidance/waiver/refund.
-- P19/P20 have conditional checks but are NOT_APPLICABLE to this allocation UPDATE.
-- SCOPE/PERMISSION rows report implemented semantics, not independent PASS tests.
-- INPUT_ERROR is missing/inconsistent/unsupported input, not a legal prohibition.
-- Read README.txt for scope, units, binding contract, and validation limits.
WITH
computed_facts AS MATERIALIZED (
WITH base AS MATERIALIZED (
  SELECT
    p.*,
    pay.account_id,
    pay.credited_date,
    pay.cycle_end,
    pay.total_cents,
    pay.minimum_cents
  FROM regz_proposals AS p
  JOIN regz_payments AS pay
    ON pay.payment_id = p.payment_id
), program_terms AS MATERIALIZED (
  SELECT
    g.*,
    (
      g.interest_accrues
      AND g.waived_on_payoff
      AND NOT g.grace_period
      AND (
        NOT g.temporary_zero OR g.retroactive_interest
      )
    ) AS qualifies
  FROM regz_programs AS g
), lot_terms AS MATERIALIZED (
  SELECT
    b.batch_id,
    b.account_id,
    b.credited_date,
    b.snapshot_date,
    bal.balance_id,
    bal.amount_cents,
    bal.protected_cents,
    bal.secured,
    bal.program_id,
    l.minimum_cents,
    l.excess_cents,
    l.effective_apr AS proposed_apr,
    l.window_start AS proposed_window,
    CASE WHEN old.balance_id IS NULL THEN 1 ELSE 0 END AS phase,
    COALESCE(old.apr, bal.apr) AS reference_apr,
    COALESCE(g.qualifies, FALSE) AS qualifies,
    COALESCE(g.qualifies AND b.credited_date BETWEEN g.start_date AND g.expiration_date, FALSE) AS active,
    g.expiration_date,
    g.grace_period,
    g.temporary_zero,
    g.retroactive_interest,
    g.interim_payment_required,
    d.qualifies AS declared
  FROM base AS b
  JOIN regz_balances AS bal
    ON bal.account_id = b.account_id AND bal.snapshot_date = b.credited_date
  JOIN regz_proposal_lines AS l
    ON l.batch_id = b.batch_id AND l.balance_id = bal.balance_id
  LEFT JOIN regz_balances AS old
    ON old.account_id = b.account_id
    AND old.balance_id = bal.balance_id
    AND old.snapshot_date = b.snapshot_date
  LEFT JOIN program_terms AS g
    ON g.program_id = bal.program_id
  LEFT JOIN regz_program_classifications AS d
    ON d.batch_id = b.batch_id AND d.program_id = bal.program_id
), lots AS MATERIALIZED (
  SELECT
    t.*,
    CASE WHEN t.active THEN 0 ELSE t.reference_apr END AS effective_apr,
    CASE
      WHEN t.active
      THEN (
        SELECT
          MIN(last_two.start_date)
        FROM (
          SELECT
            c.start_date
          FROM regz_cycles AS c
          WHERE
            c.account_id = t.account_id
            AND c.start_date <= t.expiration_date
            AND c.due_date <= t.expiration_date
          ORDER BY
            c.start_date DESC
          LIMIT 2
        ) AS last_two
      )
      ELSE NULL
    END AS window_start,
    CASE
      WHEN t.active
      THEN (
        SELECT
          c.start_date
        FROM regz_cycles AS c
        WHERE
          c.account_id = t.account_id
          AND t.expiration_date BETWEEN c.start_date AND c.end_date
          AND t.expiration_date < c.due_date
      )
      ELSE NULL
    END AS early_start
  FROM lot_terms AS t
), slices AS MATERIALIZED (
  SELECT
    l.batch_id,
    l.balance_id,
    part.disputed,
    l.phase,
    l.effective_apr,
    COALESCE(l.active AND l.credited_date BETWEEN l.window_start AND l.expiration_date, FALSE) AS in_window,
    COALESCE(
      l.active
      AND l.credited_date BETWEEN l.window_start AND l.expiration_date
      AND l.credited_date >= l.early_start,
      FALSE
    ) AS early,
    CASE
      WHEN part.disputed
      THEN l.protected_cents - MAX(0, l.minimum_cents - (
        l.amount_cents - l.protected_cents
      ))
      ELSE MAX(0, l.amount_cents - l.protected_cents - l.minimum_cents)
    END AS capacity,
    CASE
      WHEN part.disputed
      THEN MAX(
        0,
        l.excess_cents - MAX(0, l.amount_cents - l.protected_cents - l.minimum_cents)
      )
      ELSE MIN(l.excess_cents, MAX(0, l.amount_cents - l.protected_cents - l.minimum_cents))
    END AS allocated
  FROM lots AS l
  CROSS JOIN (
    SELECT
      FALSE AS disputed
    UNION ALL
    SELECT
      TRUE AS disputed
  ) AS part
), pairs AS MATERIALIZED (
  SELECT
    h.batch_id,
    h.in_window AND NOT lo.in_window AS deferred,
    h.in_window AND NOT lo.in_window AND h.early AS early,
    NOT h.in_window AND NOT lo.in_window AND h.phase < lo.phase AS historical,
    NOT h.in_window
    AND NOT lo.in_window
    AND h.phase = lo.phase
    AND h.effective_apr > lo.effective_apr AS ordinary,
    h.effective_apr = (
      SELECT
        MAX(peer.effective_apr)
      FROM slices AS peer
      WHERE
        peer.batch_id = h.batch_id
        AND peer.disputed = h.disputed
        AND peer.phase = h.phase
        AND NOT peer.in_window
        AND peer.capacity > 0
    ) AS highest
  FROM slices AS h
  JOIN slices AS lo
    ON lo.batch_id = h.batch_id AND lo.disputed = h.disputed
  WHERE
    h.capacity > 0
    AND lo.capacity > 0
    AND h.allocated < h.capacity
    AND lo.allocated > 0
), request AS MATERIALIZED (
  SELECT
    b.batch_id,
    r.*
  FROM base AS b
  JOIN regz_requests AS r
    ON r.request_id = b.request_id
  WHERE
    b.method <> 'default'
), request_targets AS MATERIALIZED (
  SELECT
    r.batch_id,
    i.*,
    l.balance_id AS existing_balance,
    l.amount_cents AS capacity,
    l.minimum_cents,
    l.secured
  FROM request AS r
  JOIN regz_request_lines AS i
    ON i.request_id = r.request_id
  LEFT JOIN lot_terms AS l
    ON l.batch_id = r.batch_id AND l.balance_id = i.balance_id
), request_allocations AS MATERIALIZED (
  SELECT
    r.batch_id,
    l.balance_id,
    l.excess_cents,
    COALESCE(i.amount_cents, 0) AS requested
  FROM request AS r
  JOIN regz_proposal_lines AS l
    ON l.batch_id = r.batch_id
  LEFT JOIN regz_request_lines AS i
    ON i.request_id = r.request_id AND i.balance_id = l.balance_id
), practice_history AS MATERIALIZED (
  SELECT
    p.*,
    LAG(p.convention) OVER w AS previous_convention,
    LAG(p.offset_days) OVER w AS previous_offset
  FROM regz_practices AS p
  WINDOW w AS (PARTITION BY p.account_id ORDER BY p.effective_date NULLS LAST)
)
SELECT
  b.batch_id,
  'allocation' AS kind,
  b.method AS method,
  b.snapshot_date AS snapshot_date,
  b.cycle_end AS cycle_end,
  b.credited_date AS credited_date,
  COALESCE(
    (
      SELECT
        r.basis
      FROM request AS r
      WHERE
        r.batch_id = b.batch_id
    ),
    'none'
  ) AS request_basis,
  COALESCE(
    (
      SELECT
        r.issuer_elected
      FROM request AS r
      WHERE
        r.batch_id = b.batch_id
    ),
    FALSE
  ) AS issuer_elected,
  COALESCE(
    (
      SELECT
        r.affirmative
      FROM request AS r
      WHERE
        r.batch_id = b.batch_id
    ),
    FALSE
  ) AS affirmative,
  COALESCE(
    (
      SELECT
        r.form_completed
      FROM request AS r
      WHERE
        r.batch_id = b.batch_id
    ),
    FALSE
  ) AS form_completed,
  COALESCE(
    (
      SELECT
        r.required_condition
      FROM request AS r
      WHERE
        r.batch_id = b.batch_id
    ),
    FALSE
  ) AS required_condition,
  COALESCE(
    (
      SELECT
        r.channel IN ('oral', 'electronic', 'written')
      FROM request AS r
      WHERE
        r.batch_id = b.batch_id
    ),
    FALSE
  ) AS contact_channel,
  EXISTS(
    SELECT
      1
    FROM request AS r
    WHERE
      r.batch_id = b.batch_id AND r.submitted_date <= b.decision_date
  ) AS request_present,
  (
    SELECT
      COUNT(*)
    FROM request AS r
    JOIN regz_request_lines AS i
      ON i.request_id = r.request_id
    WHERE
      r.batch_id = b.batch_id
  ) AS instruction_count,
  (
    SELECT
      COUNT(*)
    FROM request AS r
    JOIN regz_requests AS replacement
      ON replacement.supersedes_id = r.request_id
      AND replacement.payment_id = b.payment_id
    WHERE
      r.batch_id = b.batch_id AND replacement.submitted_date <= b.decision_date
  ) AS superseding_requests,
  EXISTS(
    SELECT
      1
    FROM request AS r
    WHERE
      r.batch_id = b.batch_id
      AND NOT r.submitted_date IS NULL
      AND EXISTS(
        SELECT
          1
        FROM regz_posted_allocations AS p
        WHERE
          p.batch_id = b.replaces_batch_id AND p.payment_id = b.payment_id
      )
      AND NOT EXISTS(
        SELECT
          1
        FROM regz_posted_allocations AS p
        WHERE
          p.batch_id = b.replaces_batch_id
          AND p.payment_id = b.payment_id
          AND (
            p.method <> 'default' OR p.decision_date > r.submitted_date
          )
      )
  ) AS prior_default_allocation,
  (
    SELECT
      COUNT(DISTINCT x.program_id)
    FROM lots AS x
    WHERE
      x.batch_id = b.batch_id AND x.active
  ) AS active_programs,
  (
    SELECT
      COUNT(DISTINCT x.program_id)
    FROM lots AS x
    WHERE
      x.batch_id = b.batch_id
      AND x.active
      AND x.credited_date BETWEEN x.window_start AND x.expiration_date
  ) AS window_programs,
  (
    SELECT
      COUNT(*)
    FROM lot_terms AS x
    WHERE
      x.batch_id = b.batch_id
      AND (
        NOT x.program_id IS NULL AND x.declared IS DISTINCT FROM x.qualifies
      )
  ) AS classification_mismatches,
  (
    SELECT
      COUNT(*)
    FROM lot_terms AS x
    WHERE
      x.batch_id = b.batch_id
      AND (
        x.interim_payment_required AND x.qualifies AND NOT x.declared
      )
  ) AS interim_payment_omissions,
  (
    SELECT
      COUNT(*)
    FROM lot_terms AS x
    WHERE
      x.batch_id = b.batch_id AND (
        x.grace_period AND x.declared
      )
  ) AS grace_classifications,
  (
    SELECT
      COUNT(*)
    FROM lot_terms AS x
    WHERE
      x.batch_id = b.batch_id
      AND (
        x.temporary_zero AND NOT x.retroactive_interest AND x.declared
      )
  ) AS zero_offer_classifications,
  (
    SELECT
      COUNT(*)
    FROM lots AS x
    WHERE
      x.batch_id = b.batch_id AND (
        x.proposed_apr IS DISTINCT FROM x.effective_apr
      )
  ) AS effective_apr_mismatches,
  (
    SELECT
      COUNT(*)
    FROM lots AS x
    WHERE
      x.batch_id = b.batch_id
      AND (
        x.proposed_window IS DISTINCT FROM x.window_start
      )
  ) AS window_start_mismatches,
  (
    SELECT
      COUNT(*)
    FROM pairs AS x
    WHERE
      x.batch_id = b.batch_id AND (
        x.ordinary AND x.highest
      )
  ) AS highest_violations,
  (
    SELECT
      COUNT(*)
    FROM pairs AS x
    WHERE
      x.batch_id = b.batch_id AND (
        x.ordinary AND NOT x.highest
      )
  ) AS remaining_violations,
  (
    SELECT
      COUNT(*)
    FROM pairs AS x
    WHERE
      x.batch_id = b.batch_id AND (
        x.ordinary
      )
  ) AS ordinary_violations,
  (
    SELECT
      COUNT(*)
    FROM pairs AS x
    WHERE
      x.batch_id = b.batch_id AND (
        x.deferred
      )
  ) AS deferred_violations,
  (
    SELECT
      COUNT(*)
    FROM pairs AS x
    WHERE
      x.batch_id = b.batch_id AND (
        x.historical
      )
  ) AS snapshot_violations,
  (
    SELECT
      COUNT(*)
    FROM pairs AS x
    WHERE
      x.batch_id = b.batch_id AND (
        x.early
      )
  ) AS early_expiry_violations,
  (
    SELECT
      COALESCE(
        SUM(
          MAX(0, x.minimum_cents + x.excess_cents - (
            x.amount_cents - x.protected_cents
          ))
        ),
        0
      )
    FROM lot_terms AS x
    WHERE
      x.batch_id = b.batch_id
  ) AS protected_reduction,
  MAX(
    0,
    b.total_cents - (
      SELECT
        COALESCE(SUM(x.amount_cents - x.protected_cents), 0)
      FROM lot_terms AS x
      WHERE
        x.batch_id = b.batch_id
    )
  ) AS unavoidable_protected_reduction,
  (
    SELECT
      COALESCE(
        SUM(
          MAX(0, x.amount_cents - x.protected_cents - x.minimum_cents - x.excess_cents)
        ),
        0
      )
    FROM lot_terms AS x
    WHERE
      x.batch_id = b.batch_id
  ) AS other_capacity_remaining,
  (
    SELECT
      CASE p.convention
        WHEN 'credit_date'
        THEN b.credited_date
        WHEN 'offset'
        THEN DATE(b.cycle_end, PRINTF('%+d days', p.offset_days))
        ELSE b.cycle_end
      END
    FROM regz_practices AS p
    WHERE
      p.account_id = b.account_id AND p.effective_date <= b.credited_date
    ORDER BY
      p.effective_date DESC
    LIMIT 1
  ) AS expected_snapshot_date,
  (
    SELECT
      COUNT(*)
    FROM practice_history AS p
    WHERE
      p.account_id = b.account_id
      AND p.effective_date <= b.credited_date
      AND NOT p.previous_convention IS NULL
      AND (
        p.convention <> p.previous_convention OR p.offset_days <> p.previous_offset
      )
      AND (
        p.authorization_evidence IS NULL OR p.authorization_evidence = ''
      )
  ) AS unauthorized_changes,
  0 AS missing_credit_cents,
  0 AS notice_count,
  (
    SELECT
      COUNT(*)
    FROM request_allocations AS x
    WHERE
      x.batch_id = b.batch_id AND x.excess_cents <> x.requested
  ) + (
    SELECT
      COUNT(*)
    FROM request_targets AS x
    WHERE
      x.batch_id = b.batch_id
      AND NOT EXISTS(
        SELECT
          1
        FROM regz_proposal_lines AS l
        WHERE
          l.batch_id = x.batch_id AND l.balance_id = x.balance_id
      )
  ) AS request_mismatches,
  (
    SELECT
      COUNT(*)
    FROM request AS r
    JOIN regz_request_lines AS i
      ON i.request_id = r.request_id
    JOIN lot_terms AS l
      ON l.batch_id = b.batch_id AND l.balance_id = i.balance_id
    WHERE
      r.batch_id = b.batch_id AND i.amount_cents > 0 AND NOT l.secured
  ) AS unsecured_request_targets,
  COALESCE(
    (
      SELECT
        CAST(NOT EXISTS(
          SELECT
            1
          FROM regz_request_lines AS i
          WHERE
            i.request_id = r.request_id
        ) AS INTEGER) + CAST((
          SELECT
            COALESCE(SUM(i.amount_cents), 0)
          FROM regz_request_lines AS i
          WHERE
            i.request_id = r.request_id
        ) <> b.total_cents - b.minimum_cents AS INTEGER) + (
          SELECT
            COUNT(*)
          FROM request_targets AS x
          WHERE
            x.batch_id = b.batch_id
            AND (
              x.existing_balance IS NULL
              OR x.amount_cents < 0
              OR x.amount_cents > x.capacity - x.minimum_cents
            )
        )
      FROM request AS r
      WHERE
        r.batch_id = b.batch_id
    ),
    0
  ) AS request_feasibility_errors
FROM base AS b
),
valid_evidence AS MATERIALIZED (
SELECT
  b.batch_id
FROM regz_proposals AS b
JOIN regz_payments AS pay
  ON pay.payment_id = b.payment_id
JOIN regz_accounts AS a
  ON a.account_id = pay.account_id
WHERE
  a.credit_card
  AND a.consumer_plan
  AND a.open_end
  AND NOT a.home_secured
  AND b.method IN ('default', 'deferred_request', 'secured_request')
  AND b.decision_date >= pay.credited_date
  AND pay.minimum_cents BETWEEN 0 AND pay.total_cents
  AND EXISTS(
    SELECT
      1
    FROM regz_snapshot_sets AS s
    WHERE
      s.account_id = pay.account_id AND s.snapshot_date = b.snapshot_date
  )
  AND EXISTS(
    SELECT
      1
    FROM regz_snapshot_sets AS s
    WHERE
      s.account_id = pay.account_id AND s.snapshot_date = pay.credited_date
  )
  AND EXISTS(
    SELECT
      1
    FROM regz_balances AS c
    WHERE
      c.account_id = pay.account_id AND c.snapshot_date = pay.credited_date
  )
  AND NOT EXISTS(
    SELECT
      1
    FROM regz_balances AS c
    WHERE
      c.account_id = pay.account_id
      AND c.snapshot_date = pay.credited_date
      AND NOT EXISTS(
        SELECT
          1
        FROM regz_proposal_lines AS l
        WHERE
          l.batch_id = b.batch_id AND l.balance_id = c.balance_id
      )
  )
  AND NOT EXISTS(
    SELECT
      1
    FROM regz_proposal_lines AS l
    WHERE
      l.batch_id = b.batch_id
      AND NOT EXISTS(
        SELECT
          1
        FROM regz_balances AS c
        WHERE
          c.account_id = pay.account_id
          AND c.snapshot_date = pay.credited_date
          AND c.balance_id = l.balance_id
      )
  )
  AND (
    SELECT
      SUM(l.minimum_cents)
    FROM regz_proposal_lines AS l
    WHERE
      l.batch_id = b.batch_id
  ) = pay.minimum_cents
  AND (
    SELECT
      SUM(l.excess_cents)
    FROM regz_proposal_lines AS l
    WHERE
      l.batch_id = b.batch_id
  ) = pay.total_cents - pay.minimum_cents
  AND (
    (
      b.replaces_batch_id IS NULL
      AND NOT EXISTS(
        SELECT
          1
        FROM regz_payment_heads AS h
        WHERE
          h.payment_id = pay.payment_id
      )
    )
    OR EXISTS(
      SELECT
        1
      FROM regz_payment_heads AS h
      WHERE
        h.payment_id = pay.payment_id AND h.batch_id = b.replaces_batch_id
    )
  )
  AND EXISTS(
    SELECT
      1
    FROM regz_practices AS p
    WHERE
      p.account_id = pay.account_id AND p.effective_date <= pay.credited_date
  )
  AND NOT EXISTS(
    SELECT
      1
    FROM regz_practices AS p
    WHERE
      p.account_id = pay.account_id
      AND p.effective_date <= pay.credited_date
      AND NOT p.convention IN ('cycle_end', 'credit_date', 'offset')
  )
  AND NOT EXISTS(
    SELECT
      1
    FROM regz_balances AS c
    JOIN regz_proposal_lines AS l
      ON l.balance_id = c.balance_id
    JOIN regz_proposals AS local_proposal
      ON local_proposal.batch_id = l.batch_id
    LEFT JOIN regz_balances AS old
      ON old.account_id = c.account_id
      AND old.balance_id = c.balance_id
      AND old.snapshot_date = local_proposal.snapshot_date
    WHERE
      l.batch_id = b.batch_id
      AND c.account_id = pay.account_id
      AND c.snapshot_date = pay.credited_date
      AND (
        c.protected_cents < 0
        OR c.protected_cents > c.amount_cents
        OR l.minimum_cents < 0
        OR l.excess_cents < 0
        OR l.minimum_cents + l.excess_cents > c.amount_cents
        OR (
          NOT old.balance_id IS NULL AND c.amount_cents > old.amount_cents
        )
        OR COALESCE(old.apr, c.apr) < 0
      )
  )
  AND NOT EXISTS(
    SELECT
      1
    FROM regz_balances AS c
    WHERE
      c.account_id = pay.account_id
      AND c.snapshot_date = pay.credited_date
      AND NOT c.program_id IS NULL
      AND (
        NOT EXISTS(
          SELECT
            1
          FROM regz_program_classifications AS d
          WHERE
            d.batch_id = b.batch_id AND d.program_id = c.program_id
        )
        OR NOT EXISTS(
          SELECT
            1
          FROM regz_programs AS g
          WHERE
            g.program_id = c.program_id
            AND g.account_id = pay.account_id
            AND g.start_date <= g.expiration_date
        )
      )
  )
  AND NOT EXISTS(
    SELECT
      1
    FROM regz_program_classifications AS d
    WHERE
      d.batch_id = b.batch_id
      AND NOT EXISTS(
        SELECT
          1
        FROM regz_balances AS c
        WHERE
          c.account_id = pay.account_id
          AND c.snapshot_date = pay.credited_date
          AND c.program_id = d.program_id
      )
  )
  AND NOT EXISTS(
    SELECT
      1
    FROM regz_balances AS bal
    JOIN regz_programs AS g
      ON g.program_id = bal.program_id
    WHERE
      bal.account_id = pay.account_id
      AND bal.snapshot_date = pay.credited_date
      AND g.interest_accrues
      AND g.waived_on_payoff
      AND NOT g.grace_period
      AND (
        NOT g.temporary_zero OR g.retroactive_interest
      )
      AND pay.credited_date BETWEEN g.start_date AND g.expiration_date
      AND (
        (
          SELECT
            COUNT(*)
          FROM regz_cycles AS c
          WHERE
            c.account_id = pay.account_id
            AND g.expiration_date BETWEEN c.start_date AND c.end_date
        ) <> 1
        OR (
          SELECT
            COUNT(*)
          FROM regz_cycles AS c
          WHERE
            c.account_id = pay.account_id
            AND c.start_date <= g.expiration_date
            AND c.due_date <= g.expiration_date
        ) < 2
        OR EXISTS(
          SELECT
            1
          FROM regz_cycles AS c
          WHERE
            c.account_id = pay.account_id
            AND EXISTS(
              SELECT
                1
              FROM regz_cycles AS n
              WHERE
                n.account_id = c.account_id AND n.start_date > c.start_date
            )
            AND DATE(c.end_date, '+1 day') <> (
              SELECT
                MIN(n.start_date)
              FROM regz_cycles AS n
              WHERE
                n.account_id = c.account_id AND n.start_date > c.start_date
            )
        )
      )
  )
  AND (
    b.method = 'default'
    OR b.request_id IS NULL
    OR EXISTS(
      SELECT
        1
      FROM regz_requests AS r
      WHERE
        r.request_id = b.request_id
        AND r.payment_id = pay.payment_id
        AND r.basis IN (
          'contact',
          'form',
          'reallocation',
          'agreement_default',
          'application_default',
          'coupon_default'
        )
    )
  )
),
proposed AS MATERIALIZED (
{{REENACT_GENERATED_SELECT}}
),
frozen AS MATERIALIZED (
    SELECT :allocation_id AS allocation_id,
           :account_id AS account_id,
           :statement_id AS statement_id,
           :payment_id AS payment_id,
           :batch_id AS batch_id,
           :proposed_cash_dollars AS proposed_cash_dollars
),
selected_state AS MATERIALIZED (
    SELECT DISTINCT p.allocation_id, p.account_id, p.statement_id,
           p.transaction_id, p.total_payment, p.minimum_payment_portion,
           p.excess_payment_amount, p.cash_advance_allocation,
           p.purchase_allocation, p.balance_transfer_allocation, p.promo_allocation
    FROM proposed p JOIN frozen f ON p.allocation_id = f.allocation_id
),
binding AS MATERIALIZED (
    SELECT CASE WHEN
      (SELECT COUNT(*) FROM selected_state) = 1
      AND EXISTS (SELECT 1 FROM valid_evidence v WHERE v.batch_id=:batch_id)
      AND (SELECT COUNT(*) FROM computed_facts c JOIN frozen f ON c.batch_id = f.batch_id) = 1
      AND (SELECT COUNT(*) FROM regz_proposals b JOIN frozen f ON b.batch_id = f.batch_id) = 1
      AND NOT EXISTS (SELECT 1 FROM computed_facts c JOIN frozen f ON c.batch_id = f.batch_id
                      WHERE c.batch_id IS NULL OR c.kind IS NULL OR c.method IS NULL OR c.request_basis IS NULL OR c.highest_violations IS NULL OR c.remaining_violations IS NULL OR c.ordinary_violations IS NULL OR c.deferred_violations IS NULL OR c.snapshot_violations IS NULL OR c.early_expiry_violations IS NULL OR c.active_programs IS NULL OR c.window_programs IS NULL OR c.unauthorized_changes IS NULL OR c.protected_reduction IS NULL OR c.unavoidable_protected_reduction IS NULL OR c.other_capacity_remaining IS NULL OR c.effective_apr_mismatches IS NULL OR c.window_start_mismatches IS NULL OR c.request_mismatches IS NULL OR c.unsecured_request_targets IS NULL OR c.request_feasibility_errors IS NULL OR c.superseding_requests IS NULL OR c.instruction_count IS NULL OR c.missing_credit_cents IS NULL OR c.notice_count IS NULL OR c.classification_mismatches IS NULL OR c.interim_payment_omissions IS NULL OR c.grace_classifications IS NULL OR c.zero_offer_classifications IS NULL OR c.issuer_elected IS NULL OR c.request_present IS NULL OR c.affirmative IS NULL OR c.contact_channel IS NULL OR c.form_completed IS NULL OR c.prior_default_allocation IS NULL OR c.required_condition IS NULL OR c.snapshot_date IS NULL OR c.cycle_end IS NULL OR c.credited_date IS NULL OR c.expected_snapshot_date IS NULL)
      AND EXISTS (
        SELECT 1 FROM selected_state p CROSS JOIN frozen f
        JOIN regz_proposals b ON b.batch_id = f.batch_id
        JOIN regz_payments pay ON pay.payment_id = b.payment_id
        JOIN computed_facts c ON c.batch_id = b.batch_id
        WHERE p.account_id = f.account_id AND p.statement_id = f.statement_id
          AND p.transaction_id = f.payment_id AND b.payment_id = f.payment_id
          AND pay.account_id = f.account_id AND c.kind = 'allocation'
          AND c.method = b.method
          AND c.snapshot_date = b.snapshot_date
          AND c.cycle_end = pay.cycle_end AND c.credited_date = pay.credited_date
          AND p.cash_advance_allocation = f.proposed_cash_dollars
          AND p.cash_advance_allocation >= 0
          AND p.purchase_allocation = 0 AND p.balance_transfer_allocation = 0
          AND p.promo_allocation = 0
          AND p.total_payment * 100 = pay.total_cents
          AND p.minimum_payment_portion * 100 = pay.minimum_cents
          AND p.excess_payment_amount * 100 = pay.total_cents - pay.minimum_cents
          AND p.cash_advance_allocation * 100 = pay.total_cents - pay.minimum_cents
          AND (SELECT COUNT(*) FROM regz_proposal_lines l
               WHERE l.batch_id = b.batch_id AND l.balance_id = f.batch_id) = 1
          AND (SELECT SUM(l.excess_cents) FROM regz_proposal_lines l
               WHERE l.batch_id = b.batch_id AND l.balance_id = f.batch_id)
               = p.cash_advance_allocation * 100
          AND (SELECT SUM(l.minimum_cents) FROM regz_proposal_lines l
               WHERE l.batch_id = b.batch_id) = pay.minimum_cents
          AND (SELECT SUM(l.excess_cents) FROM regz_proposal_lines l
               WHERE l.batch_id = b.batch_id) = pay.total_cents - pay.minimum_cents
          AND NOT EXISTS (SELECT 1 FROM regz_proposal_lines l
               WHERE l.batch_id = b.batch_id
                 AND (l.minimum_cents IS NULL OR l.excess_cents IS NULL
                      OR l.minimum_cents < 0 OR l.excess_cents < 0
                      OR (l.balance_id <> f.batch_id AND l.excess_cents <> 0)))
      )
      THEN 1 ELSE 0 END AS ok
),
-- P24: use the same classifier for every referenced program.
-- interest_accrues includes accrued finance charges; waived_on_payoff means
-- avoided, waived OR refunded on full payoff by the contractual expiration date.
-- These are trusted semantic encodings, not contract-language interpretation.
referenced_programs AS MATERIALIZED (
    SELECT DISTINCT b.program_id
    FROM frozen f
    JOIN regz_payments pay ON pay.payment_id = f.payment_id
    JOIN regz_proposal_lines l ON l.batch_id = f.batch_id
    JOIN regz_balances b ON b.account_id = f.account_id
        AND b.balance_id = l.balance_id AND b.snapshot_date = pay.credited_date
    WHERE b.program_id IS NOT NULL
),
program_definitions AS MATERIALIZED (
    SELECT r.program_id, p.account_id, p.start_date, p.expiration_date,
           p.interest_accrues, p.waived_on_payoff, p.grace_period,
           p.temporary_zero, p.retroactive_interest,
           d.qualifies AS declared_qualifies,
           CASE WHEN p.interest_accrues AND p.waived_on_payoff
                     AND NOT p.grace_period
                     AND (NOT p.temporary_zero OR p.retroactive_interest)
                THEN 1 ELSE 0 END AS defined_qualifies,
           (SELECT COUNT(*) FROM regz_programs q
             WHERE q.program_id = r.program_id) AS program_rows,
           (SELECT COUNT(*) FROM regz_program_classifications q CROSS JOIN frozen f2
             WHERE q.program_id = r.program_id AND q.batch_id = f2.batch_id) AS declaration_rows
    FROM referenced_programs r CROSS JOIN frozen f
    LEFT JOIN regz_programs p ON p.program_id = r.program_id
    LEFT JOIN regz_program_classifications d
        ON d.program_id = r.program_id AND d.batch_id = f.batch_id
),
definition_checks AS MATERIALIZED (
    SELECT CASE WHEN EXISTS (
        SELECT 1 FROM program_definitions d CROSS JOIN frozen f
        WHERE d.program_rows <> 1 OR d.declaration_rows <> 1
           OR d.account_id IS NULL OR d.account_id <> f.account_id
           OR d.start_date IS NULL OR d.expiration_date IS NULL
           OR d.start_date > d.expiration_date
           OR d.interest_accrues IS NULL OR d.waived_on_payoff IS NULL
           OR d.grace_period IS NULL OR d.temporary_zero IS NULL
           OR d.retroactive_interest IS NULL OR d.declared_qualifies IS NULL
    ) THEN 0 ELSE 1 END AS input_ok,
    CASE WHEN EXISTS (
        SELECT 1 FROM program_definitions
        WHERE declared_qualifies <> defined_qualifies
    ) THEN 0 ELSE 1 END AS classification_ok
),
-- P09-P12: the trusted context's rate counters examine excess after minimum
-- consumes capacity. It imposes no minimum formula or APR order on minimum.
-- P21-P22: those counters use strict priority comparisons on distinct lots;
-- grouping is presentation only. Do not replace them with ROW_NUMBER tie order.
-- P30-P31: default is a permitted route even with an existing/declined request.
-- These permissions are implemented by the applicability expressions below.
evaluation_scope AS MATERIALIZED (
    SELECT c.*, b.ok AS binding_ok, d.input_ok AS definition_input_ok,
           d.classification_ok,
           CASE WHEN c.kind = 'allocation' THEN 1 ELSE 0 END AS allocation_scope,
           CASE WHEN c.kind = 'correction' THEN 1 ELSE 0 END AS correction_scope,
           CASE WHEN c.kind = 'allocation' AND c.method = 'default'
                THEN 1 ELSE 0 END AS default_scope,
           CASE WHEN c.kind = 'allocation' AND c.method <> 'default'
                THEN 1 ELSE 0 END AS request_scope
    FROM binding b CROSS JOIN definition_checks d CROSS JOIN frozen f
    LEFT JOIN computed_facts c ON c.batch_id = f.batch_id
),
proposition_results AS MATERIALIZED (
    -- P01: Highest-APR priority
    SELECT 'P01' AS proposition_id,
           'Highest-APR priority' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.default_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method <> 'default' OR (s.highest_violations = 0))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Exhaust the highest effective-rate group before lower groups.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P02: Descending remainder priority
    SELECT 'P02' AS proposition_id,
           'Descending remainder priority' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.default_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method <> 'default' OR (s.remaining_violations = 0))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Compare every remaining higher/lower rate pair; equal rates remain unordered.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P03: Deferred-program applicability
    SELECT 'P03' AS proposition_id,
           'Deferred-program applicability' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN ((s.kind <> 'allocation' OR (s.classification_mismatches = 0))) AND s.classification_ok = 1 THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Runtime derives qualifying programs from conditional accrued interest and the grace/zero exclusions.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P04: Ordinary default outside the window
    SELECT 'P04' AS proposition_id,
           'Ordinary default outside the window' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.default_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method <> 'default' OR (s.active_programs = 0 OR s.window_programs > 0 OR s.ordinary_violations = 0))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Active programs outside the priority window use ordinary ordering.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P05: Deferred-window priority
    SELECT 'P05' AS proposition_id,
           'Deferred-window priority' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.default_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method <> 'default' OR (s.deferred_violations = 0))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Detect ordinary allocations while eligible priority-program capacity remains.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P06: Remainder after deferred priority
    SELECT 'P06' AS proposition_id,
           'Remainder after deferred priority' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.default_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method <> 'default' OR (s.window_programs = 0 OR s.ordinary_violations = 0))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'The ordinary balances left after the priority group retain descending effective-rate order.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P07: Optional deferred-program request
    SELECT 'P07' AS proposition_id,
           'Optional deferred-program request' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1 AND s.method = 'deferred_request') THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method <> 'deferred_request' OR (s.active_programs > 0 AND s.issuer_elected AND s.request_mismatches = 0))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'A request may allocate among any account balances while a qualifying program applies.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P08: Optional secured-balance request
    SELECT 'P08' AS proposition_id,
           'Optional secured-balance request' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1 AND s.method = 'secured_request') THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method <> 'secured_request' OR (s.unsecured_request_targets = 0 AND s.issuer_elected AND s.request_mismatches = 0))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Every positive requested amount must target a secured balance.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P09: Excess-payment scope
    SELECT 'P09' AS proposition_id,
           'Excess-payment scope' AS proposition_name,
           'SCOPE' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE 'REPRESENTED_SCOPE' END AS status,
           'Only excess enters APR ordering; minimum first consumes capacity.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P10: Minimum amount outside scope
    SELECT 'P10' AS proposition_id,
           'Minimum amount outside scope' AS proposition_name,
           'SCOPE' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE 'REPRESENTED_SCOPE' END AS status,
           'Accept the supplied minimum portion; no minimum formula is imposed.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P11: Minimum allocation outside scope
    SELECT 'P11' AS proposition_id,
           'Minimum allocation outside scope' AS proposition_name,
           'SCOPE' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE 'REPRESENTED_SCOPE' END AS status,
           'Minimum has no APR ordering requirement; whole-payment dispute protection remains.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P12: Optional minimum allocation method
    SELECT 'P12' AS proposition_id,
           'Optional minimum allocation method' AS proposition_name,
           'PERMISSION' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE 'REPRESENTED_PERMISSION' END AS status,
           'Rate-ordered and other minimum allocations are both permitted.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P13: Permitted snapshot date
    SELECT 'P13' AS proposition_id,
           'Permitted snapshot date' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.snapshot_date >= s.cycle_end AND s.snapshot_date <= s.credited_date)) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Both amounts and rates are read from the selected complete snapshot.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P14: Consistent reference-day practice
    SELECT 'P14' AS proposition_id,
           'Consistent reference-day practice' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.snapshot_date = s.expected_snapshot_date)) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Compute the date from the effective practice''s cycle-end, credit-date, or offset convention.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P15: Permitted practice adjustments
    SELECT 'P15' AS proposition_id,
           'Permitted practice adjustments' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.unauthorized_changes = 0)) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Changed conventions require a recorded authorization and effective date.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P16: Residual after historical snapshot
    SELECT 'P16' AS proposition_id,
           'Residual after historical snapshot' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.default_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method <> 'default' OR (s.snapshot_violations = 0))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'After dispute/window priorities, exhaust historical lots before later lots.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P17: Minimize disputed reduction
    SELECT 'P17' AS proposition_id,
           'Minimize disputed reduction' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.protected_reduction <= s.unavoidable_protected_reduction)) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Compute reduction for minimum plus excess against all outstanding undisputed capacity.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P18: Allow unavoidable disputed residual
    SELECT 'P18' AS proposition_id,
           'Allow unavoidable disputed residual' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.unavoidable_protected_reduction = 0 OR s.protected_reduction = 0 OR s.other_capacity_remaining = 0)) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'When disputed reduction is unavoidable, require exhaustion of all other capacity. P17 separately rejects avoidable disputed reduction.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P19: Error-correction credit
    SELECT 'P19' AS proposition_id,
           'Error-correction credit' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.correction_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'correction' OR s.missing_credit_cents = 0) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'At completion, check each required principal/charge item against actual posted credits.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P20: Correction notice dispatch
    SELECT 'P20' AS proposition_id,
           'Correction notice dispatch' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.correction_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'correction' OR s.notice_count > 0) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Require actual timely dispatch to the specified recipient, linked to the determination.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P21: Equal-rate discretion
    SELECT 'P21' AS proposition_id,
           'Equal-rate discretion' AS proposition_name,
           'PERMISSION' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE 'REPRESENTED_PERMISSION' END AS status,
           'Strict comparisons allow arbitrary splits among equal-priority slices.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P22: Grouped or separate balances
    SELECT 'P22' AS proposition_id,
           'Grouped or separate balances' AS proposition_name,
           'PERMISSION' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE 'REPRESENTED_PERMISSION' END AS status,
           'Grouped or separate presentation retains underlying lot and dispute/program distinctions.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P23: Zero allocation APR for deferred interest
    SELECT 'P23' AS proposition_id,
           'Zero allocation APR for deferred interest' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.effective_apr_mismatches = 0)) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Compare proposed effective APRs with the zero-or-snapshot-rate derivation.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P24: Incorporated deferred-interest definition
    SELECT 'P24' AS proposition_id,
           'Incorporated deferred-interest definition' AS proposition_name,
           'DEFINITION' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN s.classification_ok = 1 THEN 'PASS' ELSE 'FAIL' END END AS status,
           'All selected programs use the conditional-charge definition and exclusions, including refund semantics.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P25: Interim payments irrelevant to applicability
    SELECT 'P25' AS proposition_id,
           'Interim payments irrelevant to applicability' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.interim_payment_omissions = 0)) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Program classification does not depend on its interim-payment-required attribute.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P26: Grace-period exclusion
    SELECT 'P26' AS proposition_id,
           'Grace-period exclusion' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.grace_classifications = 0)) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'The classifier excludes grace periods.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P27: Temporary-zero exclusion
    SELECT 'P27' AS proposition_id,
           'Temporary-zero exclusion' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.zero_offer_classifications = 0)) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'The classifier excludes temporary zero APR unless accrued interest may become payable.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P28: Correct counted cycles
    SELECT 'P28' AS proposition_id,
           'Correct counted cycles' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.window_start_mismatches = 0)) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Compute the start from the latest two cycle due dates no later than expiration, not a supplied expected value.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P29: Early-expiration partial cycle
    SELECT 'P29' AS proposition_id,
           'Early-expiration partial cycle' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.default_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method <> 'default' OR (s.early_expiry_violations = 0))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Priority remains in effect after the two counted cycles until expiration.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P30: Issuer may decline requests
    SELECT 'P30' AS proposition_id,
           'Issuer may decline requests' AS proposition_name,
           'PERMISSION' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE 'REPRESENTED_PERMISSION' END AS status,
           'Default allocation is permitted whether or not a request exists; default rules still apply.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P31: Decline requests failing issuer requirements
    SELECT 'P31' AS proposition_id,
           'Decline requests failing issuer requirements' AS proposition_name,
           'PERMISSION' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE 'REPRESENTED_PERMISSION' END AS status,
           'Declining a request does not require validating it; default rules still apply.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P32: No request uses default
    SELECT 'P32' AS proposition_id,
           'No request uses default' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.allocation_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.request_present OR s.method = 'default')) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'A missing or unsubmitted request cannot activate an exception.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P33: Unfulfillable request and replacement
    SELECT 'P33' AS proposition_id,
           'Unfulfillable request and replacement' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.request_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method = 'default' OR (s.request_feasibility_errors = 0 AND s.superseding_requests = 0))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Check sums, nonnegative amounts, targets, capacities, and submitted replacement links.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P34: Affirmative specific contact
    SELECT 'P34' AS proposition_id,
           'Affirmative specific contact' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.request_scope = 1 AND s.request_basis = 'contact') THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method = 'default' OR (s.request_basis <> 'contact' OR (s.affirmative AND s.instruction_count > 0 AND s.contact_channel)))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Recognize oral/electronic/written contact with explicit structured instructions.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P35: Completed submitted request form
    SELECT 'P35' AS proposition_id,
           'Completed submitted request form' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.request_scope = 1 AND s.request_basis = 'form') THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method = 'default' OR (s.request_basis <> 'form' OR (s.form_completed AND s.request_present AND s.affirmative AND s.instruction_count > 0)))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'An actual completed/submitted form, not default coupon text, supports the exception.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P36: Request to reallocate previous payment
    SELECT 'P36' AS proposition_id,
           'Request to reallocate previous payment' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.request_scope = 1 AND s.request_basis = 'reallocation') THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method = 'default' OR (s.request_basis <> 'reallocation' OR (s.prior_default_allocation AND s.affirmative AND s.contact_channel AND s.instruction_count > 0)))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Verify a prior accepted default allocation and a later submitted specific request.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P37: Preprinted agreement is insufficient
    SELECT 'P37' AS proposition_id,
           'Preprinted agreement is insufficient' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.request_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method = 'default' OR (s.request_basis <> 'agreement_default'))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Reject reliance on agreement deemed consent; an independent contact is a different evidence record.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P38: Untouched preselection is insufficient
    SELECT 'P38' AS proposition_id,
           'Untouched preselection is insufficient' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.request_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method = 'default' OR (s.request_basis <> 'application_default'))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Reject reliance on an untouched issuer-selected checkbox.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P39: Default payment coupon is insufficient
    SELECT 'P39' AS proposition_id,
           'Default payment coupon is insufficient' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.request_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method = 'default' OR (s.request_basis <> 'coupon_default'))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Reject reliance on default coupon text or selection.' AS rationale
    FROM evaluation_scope s
    UNION ALL
    -- P40: Imposed acceptance is insufficient
    SELECT 'P40' AS proposition_id,
           'Imposed acceptance is insufficient' AS proposition_name,
           'CHECK' AS role,
           CASE WHEN s.binding_ok <> 1 OR s.definition_input_ok <> 1
                  THEN 'INPUT_ERROR'
             WHEN NOT (s.request_scope = 1) THEN 'NOT_APPLICABLE'
             ELSE CASE WHEN (s.kind <> 'allocation' OR (s.method = 'default' OR (NOT s.required_condition))) THEN 'PASS' ELSE 'FAIL' END END AS status,
           'Reject requests based on imposed acceptance.' AS rationale
    FROM evaluation_scope s
),
overall AS MATERIALIZED (
    SELECT CASE
        WHEN (SELECT ok FROM binding) <> 1
          OR (SELECT input_ok FROM definition_checks) <> 1
          OR (SELECT COUNT(*) FROM proposition_results) <> 40
          OR EXISTS (SELECT 1 FROM proposition_results WHERE status = 'INPUT_ERROR')
            THEN 'INPUT_ERROR'
        WHEN EXISTS (SELECT 1 FROM proposition_results WHERE status = 'FAIL')
            THEN 'REJECT'
        ELSE 'ALLOW'
    END AS decision
)
SELECT f.allocation_id, f.batch_id AS selected_balance_id,
       o.decision, r.proposition_id, r.proposition_name, r.role, r.status, r.rationale
FROM proposition_results r CROSS JOIN overall o CROSS JOIN frozen f
ORDER BY r.proposition_id;
